using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.CustomerPayments;public class EditModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty]public CustomerPaymentForm Item{get;set;}=null!;public SelectList Methods{get;private set;}=null!;public IReadOnlyList<PolicyOption> Policies{get;private set;}=[];public string CustomerName{get;private set;}="";public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerPayments,PermissionAction.Update))return Forbid();var x=await db.CustomerPayments.Include(x=>x.Customer).AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();Item=new(){Id=x.Id,CustomerId=x.CustomerId,CustomerDeliveryId=x.CustomerDeliveryId,Date=x.Date,Amount=x.Amount,PaymentMethodId=x.PaymentMethodId,Comments=x.Comments};CustomerName=x.Customer.Name;await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerPayments,PermissionAction.Update))return Forbid();if(ModelState.IsValid)try{await transactions.UpdateCustomerPaymentAsync(Item.Id,new(Item.CustomerId,Item.CustomerDeliveryId,Item.Date,Item.Amount,Item.PaymentMethodId,Item.Comments));TempData["Message"]="تم تعديل حركة القبض";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}CustomerName=await db.Customers.Where(x=>x.Id==Item.CustomerId).Select(x=>x.Name).FirstOrDefaultAsync()??"";await Load();return Page();}private async Task Load(){Methods=new(await db.PaymentMethods.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Policies=await transactions.GetCustomerPoliciesAsync(Item.CustomerId,Item.Id);}}
